-- ===========================================================================
-- Row-Level Security: deny-by-default org isolation on `entity_claims`
-- (docs/roadmap/entity-analysis-layer.md §3.3 — the Tanren-native defect ledger).
--
-- A Claim is PRIVATE org defect-ledger state: the policy admits a row ONLY when
-- org_id matches the request's `app.current_org_id` GUC. Unset ⇒ ZERO rows and a
-- WITH CHECK write is rejected (42501), exactly like every other 3a direct-org_id
-- tenant table (candidates / post_merge_issue_claims). NO cross-org read exception
-- (unlike `templates`, whose official tier is shared) — a defect Claim is never
-- shared across orgs. Idempotent via DROP POLICY IF EXISTS.
-- ===========================================================================
ALTER TABLE entity_claims ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS rls_org_isolation ON entity_claims;--> statement-breakpoint
CREATE POLICY rls_org_isolation ON entity_claims FOR ALL
  USING (org_id = current_setting('app.current_org_id', true))
  WITH CHECK (org_id = current_setting('app.current_org_id', true));
